#!/usr/bin/env node
// Renders every NavOSS brand PNG from its SVG source so the icon, map markers, favicons and social
// preview can be regenerated byte-for-byte. Run with `corepack pnpm --filter @navoss/site brand:render`.
// Pass `--sheet <file.png>` to also write a contact sheet of the outputs on light and dark backgrounds.

import { Resvg } from '@resvg/resvg-js';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';

const repoRoot = resolve(import.meta.dirname, '..', '..', '..');
const brandRoot = resolve(repoRoot, 'apps/mobile/assets/brand');
const imagesRoot = resolve(repoRoot, 'apps/mobile/assets/images');
const siteRoot = resolve(repoRoot, 'apps/site');
const siteAssets = resolve(siteRoot, 'src/assets');
const fontFiles = ['Regular', 'Bold'].map((weight) =>
  resolve(siteRoot, `brand/fonts/AtkinsonHyperlegibleNext-${weight}.ttf`),
);

// Community report marker colours. `fill` is the confirmed tile, `glyph` the symbol drawn on it,
// and `accent` the outline + symbol colour of the unconfirmed variant (≥ 3:1 against white).
export const REPORT_MARKERS = {
  collision: { fill: '#E5484D', glyph: '#FFFFFF', accent: '#C9353A' },
  'road-closure': { fill: '#B4232F', glyph: '#FFFFFF', accent: '#B4232F' },
  'slow-traffic': { fill: '#F5A524', glyph: '#0E1516', accent: '#A35F00' },
  construction: { fill: '#F59E0B', glyph: '#0E1516', accent: '#B45309' },
  pothole: { fill: '#F7C948', glyph: '#0E1516', accent: '#7A5D00' },
  'object-on-road': { fill: '#F7C948', glyph: '#0E1516', accent: '#7A5D00' },
  'road-hazard': { fill: '#F59E0B', glyph: '#0E1516', accent: '#B45309' },
  'stalled-vehicle': { fill: '#1E2B2C', glyph: '#FFFFFF', accent: '#1E2B2C' },
};

const read = (path) => readFileSync(path, 'utf8');

function svgBody(svg) {
  return svg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
}

// Report glyph sources draw with `currentColor` (symbol) and `var(--tile)` (knock-outs that show the
// tile colour); both tokens are substituted here because map markers must be flat PNGs.
function reportMarkerSvg(type, confirmed) {
  const colours = REPORT_MARKERS[type];
  const tile = confirmed ? colours.fill : '#FFFFFF';
  const glyph = svgBody(read(resolve(brandRoot, 'markers/report-glyphs', `${type}.svg`)))
    .replaceAll('currentColor', confirmed ? colours.glyph : colours.accent)
    .replaceAll('var(--tile)', tile);
  const face = confirmed
    ? `<rect x="9.5" y="7.5" width="45" height="45" rx="12.5" fill="${tile}"/>`
    : `<rect x="10.5" y="8.5" width="43" height="43" rx="11.5" fill="#FFFFFF" stroke="${colours.accent}" stroke-width="3" stroke-dasharray="5.5 3.5"/>`;
  const badge = confirmed
    ? '<circle cx="51" cy="51" r="10" fill="#FFFFFF"/><circle cx="51" cy="51" r="7.5" fill="#0F8F7F"/><path d="M47.4 51.2l2.4 2.4 4.8-4.9" fill="none" stroke="#FFFFFF" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>'
    : '';
  return `<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64">
<rect x="6" y="5.5" width="52" height="52" rx="16" fill="#0E1516" opacity="0.28"/>
<rect x="6" y="4" width="52" height="52" rx="16" fill="#FFFFFF"/>
${face}
<g transform="translate(32 30) scale(0.8) translate(-32 -31)">${glyph}</g>
${badge}
</svg>`;
}

function icoFromPng(png, size) {
  // A single-image ICO whose payload is the PNG itself (supported by every current browser).
  const header = Buffer.alloc(22);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(1, 4);
  header.writeUInt8(size >= 256 ? 0 : size, 6);
  header.writeUInt8(size >= 256 ? 0 : size, 7);
  header.writeUInt8(0, 8);
  header.writeUInt8(0, 9);
  header.writeUInt16LE(1, 10);
  header.writeUInt16LE(32, 12);
  header.writeUInt32LE(png.length, 14);
  header.writeUInt32LE(22, 18);
  return Buffer.concat([header, png]);
}

function render(svg, width) {
  return new Resvg(svg, {
    fitTo: { mode: 'width', value: width },
    font: { fontFiles, loadSystemFonts: false, defaultFontFamily: 'Atkinson Hyperlegible Next' },
  })
    .render()
    .asPng();
}

const outputs = [
  { source: 'icon.svg', out: resolve(imagesRoot, 'icon.png'), size: 1024 },
  {
    source: 'android-foreground.svg',
    out: resolve(imagesRoot, 'android-icon-foreground.png'),
    size: 1024,
  },
  {
    source: 'android-monochrome.svg',
    out: resolve(imagesRoot, 'android-icon-monochrome.png'),
    size: 1024,
  },
  { source: 'splash-icon.svg', out: resolve(imagesRoot, 'splash-icon.png'), size: 1024 },
  { source: 'favicon.svg', out: resolve(imagesRoot, 'favicon.png'), size: 64 },
  ...[
    ['vehicle-arrow', 64],
    ['vehicle-car', 64],
    ['camera-marker', 48],
    ['road-closure-marker', 64],
    ['road-construction-marker', 64],
    ['road-incident-marker', 64],
  ].map(([name, size]) => ({
    source: `markers/${name}.svg`,
    out: resolve(imagesRoot, `${name}.png`),
    size,
  })),
  ...Object.keys(REPORT_MARKERS).flatMap((type) => [
    { svg: reportMarkerSvg(type, true), out: resolve(imagesRoot, `report-${type}.png`), size: 64 },
    {
      svg: reportMarkerSvg(type, false),
      out: resolve(imagesRoot, `report-${type}-unconfirmed.png`),
      size: 64,
    },
  ]),
  { source: 'icon.svg', out: resolve(siteAssets, 'apple-touch-icon.png'), size: 180 },
  { source: 'favicon.svg', out: resolve(siteRoot, 'src/favicon.ico'), size: 32, ico: true },
  {
    svg: read(resolve(siteRoot, 'brand/social-preview.svg')),
    out: resolve(siteAssets, 'navoss-social-preview.png'),
    size: 1200,
  },
];

const rendered = [];
for (const output of outputs) {
  const svg = output.svg ?? read(resolve(brandRoot, output.source));
  const png = render(svg, output.size);
  mkdirSync(dirname(output.out), { recursive: true });
  writeFileSync(output.out, output.ico ? icoFromPng(png, output.size) : png);
  rendered.push({ ...output, png });
  console.log(`${relative(repoRoot, output.out)} (${String(output.size)} px)`);
}
// The site serves the vector favicon as-is.
writeFileSync(resolve(siteAssets, 'favicon.svg'), read(resolve(brandRoot, 'favicon.svg')));

const sheetIndex = process.argv.indexOf('--sheet');
if (sheetIndex !== -1) {
  const sheetPath = resolve(process.argv[sheetIndex + 1] ?? 'brand-sheet.png');
  const tiles = rendered.filter((item) => !item.ico && item.size <= 64);
  const icon = rendered.find((item) => item.out.endsWith('icon.png')).png.toString('base64');
  const cell = 96;
  const width = Math.max(tiles.length * cell, 4 * 220) + 40;
  const band = (y, background, label) => {
    let body = `<rect y="${String(y)}" width="${String(width)}" height="460" fill="${background}"/>`;
    body += `<text x="20" y="${String(y + 24)}" font-size="16" fill="${label}">NavOSS brand assets</text>`;
    [1024, 180, 60, 29].forEach((size, index) => {
      const shown = Math.min(size, 180);
      const x = 20 + index * 220;
      body += `<clipPath id="c${String(y)}${String(size)}"><rect x="${String(x)}" y="${String(y + 40)}" width="${String(shown)}" height="${String(shown)}" rx="${String(shown * 0.2237)}"/></clipPath>`;
      body += `<image href="data:image/png;base64,${icon}" x="${String(x)}" y="${String(y + 40)}" width="${String(shown)}" height="${String(shown)}" clip-path="url(#c${String(y)}${String(size)})"/>`;
      body += `<text x="${String(x)}" y="${String(y + 240)}" font-size="13" fill="${label}">${String(size)} px${size > 180 ? ' (scaled)' : ''}</text>`;
    });
    tiles.forEach((tile, index) => {
      const x = 20 + index * cell;
      body += `<image href="data:image/png;base64,${tile.png.toString('base64')}" x="${String(x)}" y="${String(y + 270)}" width="${String(tile.size)}" height="${String(tile.size)}"/>`;
      body += `<image href="data:image/png;base64,${tile.png.toString('base64')}" x="${String(x)}" y="${String(y + 350)}" width="${String(tile.size * 0.6)}" height="${String(tile.size * 0.6)}"/>`;
    });
    return body;
  };
  const sheet = `<svg xmlns="http://www.w3.org/2000/svg" width="${String(width)}" height="920">${band(0, '#E8EDE9', '#0E1516')}${band(460, '#151F20', '#F6F7F3')}</svg>`;
  writeFileSync(sheetPath, render(sheet, width));
  console.log(`Contact sheet: ${sheetPath}`);
}
